const item = $input.first().json || {};

// Build clean payload with ONLY allowed fields
const payload = {};

// Required fields
const to = item.to || item.recipient_email || item.to_email || '';
const from_addr = item.from || item.from_email || 'me';
const subject = item.subject || item.email_subject || '';

// Body: prefer html, fallback to body/text
const html = item.html || item.body || item.text || item.content || '';

if (!to) throw new Error('Missing required field: to');
if (!subject) throw new Error('Missing required field: subject');
if (!html) throw new Error('Missing required field: html/body');

payload.to = to;
payload.from = from_addr;
payload.subject = subject;
payload.html = html;

// Optional: cc ONLY if provided and non-empty
const cc = item.cc || item.cc_emails || [];
if (cc && (Array.isArray(cc) ? cc.length > 0 : String(cc).trim().length > 0)) {
  payload.cc = cc;
}

// Explicitly NEVER include bcc, text, react, headers, reply_to, scheduled_at
// This is handled by simply not adding them

return [{ json: payload }];

const resp = $input.first().json || {};
if (resp.id) {
  return [{ json: { success: true, message_id: resp.id, status: 'sent' } }];
}
if (resp.error) {
  return [{ json: { success: false, error: resp.error.message || resp.error } }];
}
return [{ json: { success: true, raw: resp } }];
